WITH flattened AS (SELECT id, effective_from, EXPLODE(tier_limits) AS tier_value FROM price_tiers), valid AS (SELECT *, DATE_FORMAT(effective_from, 'MMM yyyy') AS effective_from_label, CAST(tier_value AS DOUBLE) AS tier_value_num FROM flattened WHERE effective_from >= DATE '2024-02-19'), valid_price_tiers AS (SELECT *, DATE_TRUNC('YEAR', effective_from) AS effective_from_period FROM valid WHERE tier_value_num >= 29), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), effective_from_period) / 365 AS years_since_effective_from_period FROM valid_price_tiers WHERE effective_from > DATE '2024-05-29'), with_windows AS (SELECT *, PERCENT_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_percent_rank, CUME_DIST() OVER (PARTITION BY TO_DATE(effective_from_period) ORDER BY tier_value NULLS FIRST) AS tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY tier_value) AS tier_value_dense_rank FROM cleaned), base AS (SELECT id, effective_from, effective_from_label, tier_value_num, years_since_effective_from_period, tier_value_percent_rank, tier_value_cume_dist, tier_value_dense_rank, COALESCE(tier_value_percent_rank, 0) AS tier_value_percent_rank_filled FROM with_windows WHERE tier_value_percent_rank < 0.3), with_windows_price_tiers AS (SELECT effective_from, effective_from_label, tier_value_num, tier_value_cume_dist, tier_value_dense_rank, tier_value_percent_rank_filled, PERCENT_RANK() OVER (ORDER BY tier_value_percent_rank_filled NULLS LAST) AS tier_value_percent_rank_filled_percent_rank FROM base WHERE tier_value_dense_rank <> 3) SELECT tier_value_num, tier_value_dense_rank, tier_value_percent_rank_filled, tier_value_percent_rank_filled_percent_rank FROM with_windows_price_tiers ORDER BY tier_value_num DESC
